void zenRendering(){
 win::ProviderClient provider;auto path=win::executablePath().parent_path()/L"assets"/L"wallpapers"/L"woodland-zen-v1.png";
 auto result=provider.call(win::ProviderOperation::WorkspaceImage,win::encodeProviderTarget(path.wstring()),nullptr,5000);check(result.outcome==win::ProviderOutcome::Ok,"Bundled Zen artwork failed isolated decode");auto image=win::decodeWorkspaceImage(result.bytes);check(image&&image->width>900&&image->width>image->height*2,"Bundled Zen artwork missing or distorted");provider.close();
 ui::Graphics graphics;Host host(graphics);check(host.create(L"Owned Woodland Zen animation fixture",WS_POPUP,WS_EX_TOOLWINDOW,{120,120,1320,634}),"Zen host unavailable");host.show();SetWindowPos(host.hwnd(),HWND_TOPMOST,0,0,0,0,SWP_NOMOVE|SWP_NOSIZE|SWP_NOACTIVATE);auto monitor=win::monitors().front();monitor.bounds={120,120,1320,634};ui::LiveWallpaper wallpaper(graphics);
 check(wallpaper.update(4,{monitor},{},false,host.hwnd(),image,false),"Zen animation unavailable");pump(500);auto frames=wallpaper.frames();check(frames>=3,"Zen animation timer did not advance");HDC dc=GetDC(nullptr);const auto cottage=GetPixel(dc,140,140);auto pondPixels=[&]{HDC screen=GetDC(nullptr),memory=CreateCompatibleDC(screen);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=420;info.bmiHeader.biHeight=-80;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;void* bits=nullptr;auto bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&bits,nullptr,0);check(bitmap&&memory,"Pond capture allocation failed");auto old=SelectObject(memory,bitmap);check(BitBlt(memory,0,0,420,80,screen,500,430,SRCCOPY|CAPTUREBLT)!=FALSE,"Pond capture failed");GdiFlush();std::vector<std::uint32_t> pixels(static_cast<std::uint32_t*>(bits),static_cast<std::uint32_t*>(bits)+420*80);SelectObject(memory,old);DeleteObject(bitmap);DeleteDC(memory);ReleaseDC(nullptr,screen);return pixels;};ReleaseDC(nullptr,dc);auto pond=pondPixels();pump(1000);auto next=pondPixels();std::size_t changed=0;for(std::size_t n=0;n<pond.size();n+=7){int difference=0;for(int shift:{0,8,16})difference+=std::abs(static_cast<int>((pond[n]>>shift)&255)-static_cast<int>((next[n]>>shift)&255));if(difference>=6)++changed;}check(changed>=20,"Zen pond motion not visibly changing pixels");std::cout<<"PASS Zen pond changed "<<changed<<" sampled pixels while cottage stayed fixed\n";check(wallpaper.frames()>frames,"Zen animation stopped unexpectedly");dc=GetDC(nullptr);check(GetPixel(dc,140,140)==cottage,"Zen animation moved the cottage framing");ReleaseDC(nullptr,dc);
 check(wallpaper.update(4,{monitor},{},true,host.hwnd(),image,false),"Zen reduced-motion pause failed");pump(100);frames=wallpaper.frames();pump(250);check(wallpaper.frames()==frames,"Reduced-motion Zen kept animating");
 win::Window cover;cover.bounds=monitor.bounds;check(wallpaper.update(4,{monitor},{cover},false,host.hwnd(),image,false),"Zen cover pause failed");pump(250);check(wallpaper.frames()==frames,"Covered Zen monitor kept animating");
 check(wallpaper.update(4,{monitor},{},false,host.hwnd(),image,false),"Zen resume failed");pump(250);check(wallpaper.frames()>frames,"Zen did not resume after coverage");
 check(wallpaper.update(4,{monitor},{},false,host.hwnd(),image,true),"Zen still unavailable");pump(150);frames=wallpaper.frames();pump(250);check(frames>0&&wallpaper.frames()==frames,"Zen still has an idle timer");wallpaper.stop();check(!FindWindowExW(host.hwnd(),nullptr,L"Aether.Surface.v3",nullptr),"Zen surface leaked on stop");
 std::cout<<"PASS bundled Woodland Zen decode, advancing frames, static cottage, reduced motion, cover pause, resume and still cleanup\n";
}
int main(int argc,char** argv){SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);win::ComApartment apartment;try{if(argc==3&&std::string_view(argv[1])=="--apply-zen"){auto profile=std::filesystem::path(win::wide(argv[2]));check(profile.is_absolute()&&std::filesystem::is_directory(profile),"Explicit existing profile required");win::setConfigDirectory(profile);win::Workspaces workspaces;check(workspaces.refresh()&&workspaces.available(),"Workspace backend unavailable");for(const auto& item:workspaces.items())if(item.current){const auto id=item.id;check(workspaces.setAppearance(id,{9,{}}),"Zen workspace preference save failed");auto controller=FindWindowW(L"Aether.Controller.v3",L"Aether UI Controller");DWORD owner=0;GetWindowThreadProcessId(controller,&owner);check(controller&&win::processPath(owner)==(win::executablePath().parent_path()/L"AetherUI.exe").wstring(),"Expected staged controller missing");PostMessageW(controller,win::WorkspaceChangedMessage,0,0);std::cout<<"PASS Woodland Zen applied to current workspace\n";return 0;}throw std::runtime_error("Current workspace unavailable");}codec();providerImage();std::cout<<"PASS isolated workspace image decoding, bounds, exact pixels and unchanged icon limits\n";preferences(argc==2&&std::string_view(argv[1])=="--actions");std::cout<<"PASS workspace names, GUID affinity, persistence, validation and profile recovery\n";stillRendering();zenRendering();std::cout<<"PASS still/picture wallpaper pixels, idle timer retirement and owned cleanup\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL workspace personalization: "<<e.what()<<'\n';return 1;}}
